"<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><title>Astro Remote</title>"
"<style>*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#090d13;color:#edf4ff;font-family:Arial,sans-serif}body{background:radial-gradient(circle at 50% 0,#142238 0,#090d13 42%,#06080c 100%)}header{height:64px;display:flex;align-items:center;gap:12px;padding:0 18px;border-bottom:1px solid #263447;background:rgba(9,13,19,.94)}header a{color:#c8d6e8;text-decoration:none;font-weight:800}.brand{font-weight:900;letter-spacing:.09em}.spacer{flex:1}.pill{padding:6px 9px;border:1px solid #34465f;border-radius:999px;color:#9eb1c8;font-size:12px}.pill.on{color:#9ee7bb;border-color:#315841}.pill.bad{color:#ffb6bf;border-color:#61323b}main{padding:22px;max-width:1180px;margin:0 auto}.grid{display:grid;grid-template-columns:minmax(0,1fr) 410px;gap:16px}.screen{aspect-ratio:16/9;background:#020304;border:1px solid #28394f;border-radius:16px;display:grid;place-items:center;overflow:hidden;box-shadow:0 28px 90px rgba(0,0,0,.38)}.screen-inner{text-align:center;padding:26px}.screen h2{margin:0 0 8px}.screen p{margin:0;color:#7f93aa;line-height:1.5}.pin{font-size:54px;font-weight:900;letter-spacing:.15em;margin:18px 0 8px}.account{font-family:monospace;font-size:16px;color:#b9c9dc;word-break:break-all}.panel{border:1px solid #29394e;background:#0f1620;border-radius:16px;padding:18px;height:max-content}.panel h3{margin:0 0 16px}.row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #202c3b;font-size:13px}.row span:first-child{color:#8397af}.row span:last-child{text-align:right;font-weight:700;word-break:break-word}.warn{margin-top:14px;padding:12px;border:1px solid #684e2c;border-radius:10px;background:#20180e;color:#ffd89a;font-size:12px;line-height:1.5}.okbox{margin-top:14px;padding:12px;border:1px solid #315841;border-radius:10px;background:#102018;color:#a7e9ba;font-size:12px;line-height:1.5}button{width:100%;margin-top:10px;padding:11px;border-radius:9px;border:1px solid #405676;background:#162235;color:#eaf2ff;font-weight:800;cursor:pointer}.primary{background:#d8e7f8;color:#091019;border-color:#d8e7f8}.danger{background:#261519;border-color:#61323b;color:#ffb6bf}.secondary{background:#151c26;color:#c9d8e9;border-color:#34465f}.activate{background:#342614;border-color:#80613a;color:#ffe0a6}button:disabled{opacity:.5}.note{margin-top:14px;color:#71859d;font-size:12px;line-height:1.5}.error{margin-top:12px;color:#ff9da9;font-size:12px;display:none}@media(max-width:820px){.grid{grid-template-columns:1fr}main{padding:12px}.pin{font-size:38px}}</style></head><body>"
"<header><a href='/'>← Astro</a><span class='brand'>REMOTE SERVICE</span><span id='servicePill' class='pill'>WORKER</span><span class='spacer'></span><span id='phasePill' class='pill'>IDLE</span></header>"
"<main><div class='grid'><section class='screen'><div class='screen-inner'><h2 id='screenTitle'>Preparando Astro Remote</h2><p id='screenText'>O Astro valida a conta ativa antes do pareamento.</p><div id='pin' class='pin'>--------</div><div id='account' class='account'></div><p id='timer'></p></div></section><aside class='panel'><h3>Conta ativa</h3>"
"<div class='row'><span>Leitura</span><span id='accRc'>...</span></div><div class='row'><span>Nome</span><span id='accName'>...</span></div><div class='row'><span>UID</span><span id='accUid'>...</span></div><div class='row'><span>Slot</span><span id='accSlot'>...</span></div><div class='row'><span>Account ID</span><span id='accId'>...</span></div><div class='row'><span>Tipo</span><span id='accType'>...</span></div><div class='row'><span>Flags</span><span id='accFlags'>...</span></div><div class='row'><span>Status</span><span id='accStatus'>...</span></div>"
"<div id='activationBox' class='warn' style='display:none'>Conta offline não ativada. O Astro pode aplicar a mesma fake activation do OffAct somente ao usuário que está em primeiro plano. Confira os dados acima antes de confirmar.<br><br><b>Novo Account ID:</b> <span id='proposedId'></span><button id='activate' class='activate'>FAKE ATIVAR ESTE USUÁRIO</button></div>"
"<div id='rebootBox' class='warn' style='display:none'><b>Ativação concluída.</b><br>Reinicie o PS5 antes de continuar. Depois do reboot, faça o jailbreak novamente e abra o Astro.</div>"
"<div id='readyBox' class='okbox' style='display:none'>Conta pronta para Remote Play offline. O Astro pode gerar o PIN sem login na PSN.</div>"
"<h3 style='margin-top:20px'>Remote Play</h3><div class='row'><span>Worker</span><span id='worker'>...</span></div><div class='row'><span>Uso remoto</span><span id='rpEnabled'>...</span></div><div class='row'><span>Servidor 9295</span><span id='rpPort'>...</span></div><div class='row'><span>Pareamento</span><span id='pairing'>...</span></div><div class='row'><span>Erro RP</span><span id='pairErr'>-</span></div>"
"<button id='pair' class='primary'>GERAR PIN OFFLINE</button><button id='cancel' class='danger'>CANCELAR PAREAMENTO</button><button id='refresh' class='secondary'>RELER USUÁRIO ATIVO</button><button id='restart' class='secondary'>REINICIAR SERVIÇO INTERNO</button><div id='error' class='error'></div><div class='note'>Fluxo: detectar conta → fake ativar se necessário → reiniciar → gerar PIN → parear → remoto. O Astro nunca escolhe outro slot manualmente: a ativação é sempre do usuário em primeiro plano.</div></aside></div></main>"
"<script>const $=id=>document.getElementById(id);let busy=false;function lock(v){busy=v;['activate','pair','cancel','refresh','restart'].forEach(x=>$(x).disabled=v)}function err(t){$('error').textContent=t||'';$('error').style.display=t?'block':'none'}function pinfmt(n){n=String(Number(n)||0).padStart(8,'0');return n.slice(0,4)+' '+n.slice(4)}function hex(n){n=Number(n)||0;return n?'0x'+(n>>>0).toString(16).toUpperCase():'-'}async function status(){try{let j={};try{const sr=await fetch('/api/remote/status',{cache:'no-store'});j=await sr.json()}catch(e){}const wr=await fetch('/service/remote/_root/status',{cache:'no-store'});const w=await wr.json();if(!wr.ok)throw new Error(w.error||('worker HTTP '+wr.status));const online=!!j.service_online,pin=!!w.pairing_pin_ready,done=!!w.pairing_complete,active=!!w.pairing_active,activated=!!w.account_activated,reboot=!!w.reboot_required,arc=Number(w.account_rc);$('accRc').textContent=arc===0?'OK':('rc='+arc);$('accName').textContent=w.account_name||'-';$('accUid').textContent=String(w.account_user||0);$('accSlot').textContent=(w.account_slot?String(w.account_slot):'-')+'/16';$('accId').textContent=w.account_id_hex||'-';$('accType').textContent=w.account_type||'(offline)';$('accFlags').textContent=String(w.account_flags||0);$('accStatus').textContent=arc!==0?'FALHA NA LEITURA':(activated?'FAKE ATIVADA':'OFFLINE NÃO ATIVADA');$('proposedId').textContent=w.account_proposed_id_hex||'-';$('activationBox').style.display=(arc===0&&!activated&&!reboot)?'block':'none';$('rebootBox').style.display=reboot?'block':'none';$('readyBox').style.display=(arc===0&&activated&&!reboot)?'block':'none';$('pair').style.display=(arc===0&&activated&&!reboot)?'block':'none';$('worker').textContent=j.worker_pid?('astrorem PID '+j.worker_pid):('astrorem PID '+String(w.pid||'?'));$('rpEnabled').textContent=w.remoteplay_enabled?'HABILITADO':'DESATIVADO';$('rpPort').textContent=w.remoteplay_tcp_9295?'RESPONDENDO':'SEM RESPOSTA';$('pairing').textContent=done?'CONCLUÍDO':(active?'AGUARDANDO DISPOSITIVO':'PARADO');$('pairErr').textContent=hex(w.pairing_error);$('pin').textContent=pin?pinfmt(w.pairing_pin):'--------';$('account').textContent=pin?('Account ID: '+w.pairing_account_id):'';$('timer').textContent=pin?('Tempo restante: '+String(w.pairing_seconds_left||0)+'s'):'';$('servicePill').textContent=online?'WORKER ONLINE':'WORKER';$('servicePill').className='pill '+(online?'on':'');$('phasePill').textContent=(w.phase||j.phase||'idle').replaceAll('_',' ').toUpperCase();if(arc!==0){$('screenTitle').textContent='Falha ao ler usuário ativo';$('screenText').textContent='O código rc='+arc+' identifica exatamente em qual etapa a leitura falhou.'}else if(reboot){$('screenTitle').textContent='Reinicie o PS5';$('screenText').textContent='A fake activation foi gravada. O reboot é obrigatório antes do pareamento.'}else if(done){$('screenTitle').textContent='Pareamento concluído ✓';$('screenText').textContent='O PS5 confirmou o registro do dispositivo.'}else if(pin){$('screenTitle').textContent='PIN real do Remote Play';$('screenText').textContent='Use este PIN no cliente que estiver registrando.'}else if(!activated){$('screenTitle').textContent='Conta offline detectada';$('screenText').textContent='Confira usuário, slot e Account ID antes de fake ativar.'}else{$('screenTitle').textContent='Conta pronta';$('screenText').textContent='Agora o Astro pode gerar o PIN offline pelo método LinkDev.'}err('')}catch(e){err(String(e.message||e))}}async function act(path){if(busy)return;lock(true);err('');try{const r=await fetch(path,{method:'POST'});const j=await r.json();if(!r.ok){const rc=typeof j.rc==='undefined'?'?':j.rc;throw new Error((j.error||'Falha')+' rc='+rc)}await status()}catch(e){err(String(e.message||e));await status()}finally{lock(false)}}$('activate').onclick=()=>{const name=$('accName').textContent,uid=$('accUid').textContent,slot=$('accSlot').textContent,id=$('proposedId').textContent;if(confirm('Fake ativar este usuário?\n\nNome: '+name+'\nUID: '+uid+'\nSlot: '+slot+'\nNovo Account ID: '+id+'\n\nDepois será necessário reiniciar o PS5.'))act('/service/remote/_root/account/activate')};$('pair').onclick=()=>act('/service/remote/_root/pairing/prepare');$('cancel').onclick=()=>act('/service/remote/_root/pairing/cancel');$('refresh').onclick=()=>act('/service/remote/_root/account/refresh');$('restart').onclick=()=>act('/api/remote/restart');status();setInterval(()=>{if(!busy)status()},1000);</script></body></html>";

